import{_ as a,c as s,a as e,o as t}from"./app-C1s5HV2F.js";const o={};function c(p,n){return t(),s("div",null,n[0]||(n[0]=[e(`<h1 id="accessing-array-elements" tabindex="-1"><a class="header-anchor" href="#accessing-array-elements"><span>Accessing Array Elements</span></a></h1><p>You can access the elements in an array by using the index number. An index number refers to a unique numeric ID that represents the position of elements in an array.</p><p>Indexing in the <code>openMadness</code> starts from 0. I.e., if there are four elements in an array, e.g., 5, 9, 10, and 3. The first number <code>5</code> has an index of <code>0</code>, the second number <code>9</code> has an index of <code>1</code>, the third number <code>10</code> has an index of <code>3</code>, and so on. How to Access an Element in an Array You can access an element in an array by enclosing its index number in a bracket <code>[ ]</code> beside the variable.</p><p>Example:</p><div class="language-om line-numbers-mode" data-highlighter="prismjs" data-ext="om"><pre><code><span class="line">import { omArray } from &#39;openmadness&#39;;</span>
<span class="line">  const age = onArray [18, 25, 17, 23, 11 ];</span>
<span class="line">  console.log(age [ 4] ); // 2 represents the index number of age 11</span>
<span class="line">  console.log( age [0]) //  0 represents the index number of age 18</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="how-to-access-more-than-one-element-in-an-array" tabindex="-1"><a class="header-anchor" href="#how-to-access-more-than-one-element-in-an-array"><span>How to Access More Than One Element in an Array</span></a></h2><p>You can access more than one element in an array by enclosing all the index numbers you want to retrieve in a bracket <code>[ ]</code> beside the variable. Example:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> omArray <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> age <span class="token operator">=</span> onArray <span class="token punctuation">[</span><span class="token number">18</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">,</span> <span class="token number">23</span><span class="token punctuation">,</span> <span class="token number">11</span> <span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>age <span class="token punctuation">[</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">4</span> <span class="token punctuation">]</span> <span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// This retrieves age 17 and 11</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span> age <span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token comment">//  This retrieves age 18 and 17 </span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="how-to-access-all-the-elements-in-an-array" tabindex="-1"><a class="header-anchor" href="#how-to-access-all-the-elements-in-an-array"><span>How to Access All the Elements in an Array</span></a></h2><p>You can access all the elements in an array by passing the array variable. <strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> omArray <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> age <span class="token operator">=</span> onArray <span class="token punctuation">[</span><span class="token number">18</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">,</span> <span class="token number">23</span><span class="token punctuation">,</span> <span class="token number">11</span> <span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>age <span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// This retrieves all the age numbers.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,11)]))}const i=a(o,[["render",c]]),r=JSON.parse('{"path":"/guides/fundamentals/array-elements.html","title":"Accessing Arrays","lang":"en-US","frontmatter":{"lang":"en-US","title":"Accessing Arrays","description":"Get to know how to access array elements in openmadness library"},"headers":[{"level":2,"title":"How to Access More Than One Element in an Array","slug":"how-to-access-more-than-one-element-in-an-array","link":"#how-to-access-more-than-one-element-in-an-array","children":[]},{"level":2,"title":"How to Access All the Elements in an Array","slug":"how-to-access-all-the-elements-in-an-array","link":"#how-to-access-all-the-elements-in-an-array","children":[]}],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"guides/fundamentals/array-elements.md"}');export{i as comp,r as data};
